#!/usr/bin/env python3

import json
from dataclasses import dataclass, field
from typing import List
import jsonschema

from mashumaro.jsonschema import build_json_schema


@dataclass
class NestedObject:
    value: int
    name: str = "default"


@dataclass 
class WritableManifest:
    id: str
    version: int
    items: List[NestedObject] = field(default_factory=list)


def test_manual_fix():
    """Test what happens if we manually fix the reference path."""

    schema_with_refs = build_json_schema(WritableManifest, all_refs=True)
    schema_dict = schema_with_refs.to_dict()

    print("Original schema:")
    print(json.dumps(schema_dict, indent=2))
    print()

    # The problem: reference uses #/defs/ but definitions are in $defs/
    # Let's manually fix the reference to use #/$defs/
    if "$ref" in schema_dict and schema_dict["$ref"] == "#/defs/WritableManifest":
        schema_dict["$ref"] = "#/$defs/WritableManifest"
        print("Fixed schema (changed reference to #/$defs/):")
        print(json.dumps(schema_dict, indent=2))
        print()

        # Test validation with fixed reference
        test_data = {
            "id": "test-123",
            "version": 1,
            "items": [
                {"value": 42, "name": "item1"},
                {"value": 100, "name": "item2"}
            ]
        }

        try:
            jsonschema.validate(test_data, schema_dict)
            print("✓ Validation with FIXED reference: SUCCESS")
        except Exception as e:
            print(f"✗ Validation with FIXED reference: FAILED - {e}")
            print(f"   Error type: {type(e).__name__}")
    else:
        print("Reference not in expected format")


def test_root_schema_not_reference():
    """Test what happens if root schema is not a reference."""

    schema_with_refs = build_json_schema(WritableManifest, all_refs=True)
    schema_dict = schema_with_refs.to_dict()

    print("\nTesting approach: Root schema is not a reference")

    # Extract the actual schema from definitions and make it the root
    if "$ref" in schema_dict and "$defs" in schema_dict:
        ref_target = schema_dict["$ref"]  # "#/defs/WritableManifest"
        defs_key = ref_target.split("/")[-1]  # "WritableManifest"

        if defs_key in schema_dict["$defs"]:
            # Replace root schema with the actual definition
            root_schema = schema_dict["$defs"][defs_key]
            # Remove the reference and keep definitions
            del schema_dict["$ref"]
            # Put the root schema content at the top level
            for key, value in root_schema.items():
                schema_dict[key] = value

            print("Modified schema (root is actual schema, not reference):")
            print(json.dumps(schema_dict, indent=2))
            print()

            # Test validation
            test_data = {
                "id": "test-123",
                "version": 1,
                "items": [
                    {"value": 42, "name": "item1"},
                    {"value": 100, "name": "item2"}
                ]
            }

            try:
                jsonschema.validate(test_data, schema_dict)
                print("✓ Validation with ROOT AS SCHEMA: SUCCESS")
            except Exception as e:
                print(f"✗ Validation with ROOT AS SCHEMA: FAILED - {e}")
                print(f"   Error type: {type(e).__name__}")
        else:
            print(f"Definition key '{defs_key}' not found in definitions")


if __name__ == "__main__":
    test_manual_fix()
    test_root_schema_not_reference()

